import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const artifactPath = path.join(
  root,
  "artifacts",
  "contracts",
  "TicketChain.sol",
  "TicketChain.json",
);
const outPath = path.join(root, "src", "chain", "abi.ts");

let artifact: { abi: unknown[] };
try {
  artifact = JSON.parse(await readFile(artifactPath, "utf8")) as { abi: unknown[] };
} catch {
  console.error(`Cannot read ${artifactPath}. Run "npm run compile" first.`);
  process.exit(1);
}

const source =
  "// Generated by scripts/export-abi.ts from the Hardhat artifact. Do not edit.\n" +
  `export const ticketChainAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;

await mkdir(path.dirname(outPath), { recursive: true });
await writeFile(outPath, source);
console.log(`Wrote ${path.relative(root, outPath)} (${artifact.abi.length} ABI entries)`);
